def handle(args, state, ds):
    report = ds.consistency_report()
    if report.get('pending', 0) == 0:
        return {'status': 'complete', 'remaining': []}
    return {'status': 'remaining', 'detail': report.get('detail', 'reconciliation in progress')}

def handle(args, state, ds):
    status = ds.sync_status()
    if status.get('drift', True) is False:
        return {'status': 'synced', 'detail': 'toolchain matches requested configuration'}
    return {'status': 'drifting', 'detail': status.get('detail', 'installation not yet settled')}

